            if start < c:
                col_bands.append((start, c))
            start = c + 1
    if start < w:
        col_bands.append((start, w))

    points = {}
    for i, (r0, r1) in enumerate(row_bands):
        for j, (c0, c1) in enumerate(col_bands):
            for r in range(r0, r1):
                for c in range(c0, c1):
                    color = grid[r][c]
                    if color not in (0, 8):
                        points.setdefault(color, []).append((i, j))

    strokes = {}
    for color, pts in points.items():
        # Matching markers in the same band define a segment between them.
        for i in range(len(row_bands)):
            js = [j for ri, j in pts if ri == i]
            if len(js) >= 2:
                for j in range(min(js), max(js) + 1):
                    strokes.setdefault((i, j), []).append(color)
        for j in range(len(col_bands)):
            is_ = [i for i, cj in pts if cj == j]
            if len(is_) >= 2:
                for i in range(min(is_), max(is_) + 1):
                    strokes.setdefault((i, j), []).append(color)

    out = [row[:] for row in grid]
    for (i, j), colors in strokes.items():
        color = colors[0]
        for other in colors[1:]:
